#!/usr/bin/env node
// Writes components/terminal/xtermBundle.generated.ts: xterm.js, its fit,
// Unicode 11 and web-links addons and CSS as strings, for the terminal page the native app shows in a
// WebView (the web app imports the packages directly). Run
// `npm run vendor-xterm` after updating @xterm/xterm or one of its addons.

import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (p) => readFile(join(root, "node_modules", p), "utf8");

const [xterm, fit, unicode11, webLinks, css] = await Promise.all([
  read("@xterm/xterm/lib/xterm.js"),
  read("@xterm/addon-fit/lib/addon-fit.js"),
  read("@xterm/addon-unicode11/lib/addon-unicode11.js"),
  read("@xterm/addon-web-links/lib/addon-web-links.js"),
  read("@xterm/xterm/css/xterm.css"),
]);
const strip = (s) => s.replace(/\n\/\/# sourceMappingURL=.*$/m, "");
const out = `// Generated by scripts/vendor-xterm.mjs; do not edit.
/* eslint-disable */
export const XTERM_JS = ${JSON.stringify(strip(xterm))};
export const FIT_JS = ${JSON.stringify(strip(fit))};
export const UNICODE11_JS = ${JSON.stringify(strip(unicode11))};
export const WEB_LINKS_JS = ${JSON.stringify(strip(webLinks))};
export const XTERM_CSS = ${JSON.stringify(css)};
`;
await writeFile(join(root, "components/terminal/xtermBundle.generated.ts"), out);
console.log("wrote components/terminal/xtermBundle.generated.ts");
